// Build the hs2 host-service rollout archives (Linux: warden; Windows: minipc) from a TREE, with the package pins that
// tree actually has - refreshable against final main without editing this file (work/hosted-services-activation).
//   node build-stage-r2.mjs --tree <dir> [--app-static <capture.json>] [--allow-stale-packages] [--out <dir>]
//   node build-stage-r2.mjs --tree <dir> ... --check        rebuild in a temporary directory; require identical archives
// The tree's packages must be CURRENT (`node scripts/build-host-service-packages.mjs --check` passes there) unless
// --allow-stale-packages (isolated tests only; recorded in STAGE-INPUTS.json as packagesCurrent:false - never stage that).
// Inputs (all public; recorded with sha256 in each archive's STAGE-INPUTS.json): the tree (runner + tool bundled from it,
// four role packages copied byte-exact), the fleet directory's public config fields, the 936-object bootstrap manifest the
// fleet replicas serve, root's warden listener capture, an optional APP_STATIC capture (stage-tool capture-app-static),
// and the Windows supervisor binary out/windows/hostsvc-supervisor.exe (job-go.sh, reproducible).
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { createHash } from 'node:crypto';
import { createRequire } from 'node:module';
import { execFileSync } from 'node:child_process';
import { fileURLToPath, pathToFileURL } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url)), W = path.resolve(HERE, '..');
const LABEL = 'hs2';
const ROLES4 = ['directory-replica', 'bootstrap-replica', 'route-dns', 'policy-mirror'];
const BOOTSTRAP_MANIFEST = { file: path.join(W, 'adapter-retained/manifest.next.json'), sha256: '62c4ed1b40f2731be1d6124f81b0dd65c13a4b1626afaa47910e8801ee8d73ca' };
const NS = ['ns-us-west.enclave.host', 'ns-eu-central.enclave.host', 'ns-ap-southeast.enclave.host', 'ns-ca-east.enclave.host'];
const sha = (b) => createHash('sha256').update(b).digest('hex');
const argv = process.argv.slice(2), flag = (n) => { const i = argv.indexOf(n); return i >= 0 ? argv[i + 1] : undefined; };

async function bundle(TREE, esbuild, entry, outfile, { ownEntryCheck }) {
  const r = await esbuild.build({ absWorkingDir: TREE, entryPoints: [entry], outfile, write: false, metafile: true, bundle: true, platform: 'node', format: 'esm',
    target: 'node22', legalComments: 'none',
    banner: { js: `// Generated by work/hosted-services-activation/build-stage-r2.mjs from ${entry}; do not edit.\nimport {createRequire as __enclaveStageCreateRequire} from "node:module"; const require=__enclaveStageCreateRequire(import.meta.url);` } });
  const bytes = Buffer.from(r.outputFiles[0].contents);
  const probe = path.join(os.tmpdir(), `stage-probe-${process.pid}-${path.basename(outfile)}`);
  try { fs.writeFileSync(probe, bytes); execFileSync(process.execPath, ['--check', probe], { stdio: ['ignore', 'ignore', 'pipe'] }); }
  catch (e) { throw new Error(`${entry}: the bundle does not parse: ${String(e.stderr || e.message).slice(0, 400)}`); }
  finally { fs.rmSync(probe, { force: true }); }
  const checks = (bytes.toString('utf8').match(/process\.argv\[1\]\s*&&[^\n]{0,200}import\.meta\.url/g) || []).length;
  if (ownEntryCheck && checks !== 1) throw new Error(`${entry}: ${checks} "main module" checks in the bundle; exactly its own is allowed`);
  const inputs = {};
  for (const rel of Object.keys(r.metafile.inputs).sort()) {
    const norm = rel.includes('node_modules/') ? 'node_modules/' + rel.split('node_modules/').pop() : rel;
    inputs[norm] = sha(fs.readFileSync(path.resolve(TREE, rel)));
  }
  return { bytes, inputs };
}
function fleetDirectory() {
  let ref = null, cfg = null; const facts = {};
  for (const h of ['us-west', 'eu-central', 'ap-southeast', 'ca-east']) {
    const f = path.join(W, `directory-runtime-activation/hosts/${h}.facts.json`), raw = fs.readFileSync(f);
    const c = JSON.parse(raw).configs['/etc/enclave-directory/config-f6959cb.json'];
    const t = JSON.stringify([c.addressBook.toLowerCase(), c.checkers, c.authorityPins, c.rpcOrigins]);
    if (ref && t !== ref) throw new Error(`fleet directory configuration differs on ${h}`);
    ref = t; cfg = c; facts[`work/directory-runtime-activation/hosts/${h}.facts.json`] = sha(raw);
  }
  return { cfg, facts };
}
function archive(outDir, stageRoot, name) {
  const tar = path.join(outDir, `${name}.tar`);
  execFileSync('tar', ['--sort=name', '--mtime=@0', '--owner=0', '--group=0', '--numeric-owner', '--format=gnu', '-C', stageRoot, '-cf', tar, name]);
  const digest = sha(fs.readFileSync(tar));
  fs.writeFileSync(`${tar}.sha256`, `${digest}  ${path.basename(tar)}\n`);
  return { tar, digest };
}
function sums(S) {
  const files = [];
  const walk = (d) => { for (const n of fs.readdirSync(d).sort()) { const p = path.join(d, n); if (fs.statSync(p).isDirectory()) walk(p); else files.push(path.relative(S, p)); } };
  walk(S);
  fs.writeFileSync(path.join(S, 'STAGE-SHA256SUMS'), files.filter((f) => f !== 'STAGE-SHA256SUMS').map((f) => `${sha(fs.readFileSync(path.join(S, f)))}  ${f}`).join('\n') + '\n');
  fs.chmodSync(path.join(S, 'STAGE-SHA256SUMS'), 0o644);
  return files.length + 1;
}

export async function build({ tree, outRoot, appStaticFile = null, allowStale = false }) {
  const TREE = path.resolve(tree);
  const esbuild = createRequire(path.join(TREE, 'package.json'))('esbuild');
  // 1. the tree's packages: self-consistent, and CURRENT with the tree's sources unless explicitly allowed for a test
  const pins = {}, pkgDir = path.join(TREE, 'network/host-services/packages');
  for (const role of ROLES4) {
    const man = fs.readFileSync(path.join(pkgDir, `${role}.package.json`)), m = JSON.parse(man);
    if (sha(fs.readFileSync(path.join(pkgDir, m.bundle))) !== m.bundleSha256) throw new Error(`${role}: bundle does not match its manifest`);
    pins[role] = 'sha256:' + sha(man);
  }
  let packagesCurrent = true;
  try { execFileSync(process.execPath, ['scripts/build-host-service-packages.mjs', '--check'], { cwd: TREE, stdio: ['ignore', 'pipe', 'pipe'] }); }
  catch (e) { packagesCurrent = false; if (!allowStale) throw new Error(`the tree's packages are STALE (refresh them in the tree first): ${String(e.stderr || e.message).slice(0, 300)}`); }
  // 2. public inputs
  const { cfg: fleet, facts } = fleetDirectory();
  const indexPin = JSON.parse(fs.readFileSync(path.join(TREE, 'contracts/deployments/service-index-activation-base.json'), 'utf8')).indexPin;
  let appStatic = {}, appStaticInput = null;
  if (appStaticFile) {
    const raw = fs.readFileSync(appStaticFile), cap = JSON.parse(raw);
    appStatic = cap.labels || {};
    appStaticInput = { file: path.basename(appStaticFile), sha256: sha(raw), capturedAt: cap.at, servers: cap.servers, refused: (cap.refused || []).length };
  }
  const { ROLES } = await import(pathToFileURL(path.join(TREE, 'network/host-services/roles.mjs')).href);
  if (Object.keys(appStatic).length) ROLES['route-dns'].validate({ dnsPort: 53, bind: '127.0.0.1', apiPort: 1, zone: 'app.enclave.host', ipZone: 'ip.enclave.host',
    nsName: NS[0], nsNames: NS, routeMapUrl: 'http://127.0.0.1:1/v1/network/routes', appStatic });
  const manifest = fs.readFileSync(BOOTSTRAP_MANIFEST.file);
  if (sha(manifest) !== BOOTSTRAP_MANIFEST.sha256) throw new Error('bootstrap manifest is not the fleet-served 62c4ed1b...');
  const common = { bind: '127.0.0.1', ports: { directory: 18188, bootstrap: 18189, dns: 18153, dnsApi: 18154, policy: 18190 }, serviceIndex: indexPin, pins,
    directoryRpc: fleet.rpcOrigins, authorityPins: fleet.authorityPins, checkers: fleet.checkers, directoryPeers: fleet.peers.concat(['http://134.199.235.187:8188']).sort() };
  const provenance = {
    directory: 'the fleet directory config-f6959cb.json public fields (identical on all four machines)',
    dns: 'fleet zones and NS set; this replica\'s own NS name is NOT delegated (root decision)',
    appStatic: appStaticInput ? 'stage-tool capture-app-static: authoritative answers of every listed server, all agreeing' : 'NONE CAPTURED: no static label is served until capture-app-static output is supplied',
    bootstrapManifest: 'work/adapter-retained/manifest.next.json: the 936 objects the four fleet replicas serve',
  };
  const linuxSpec = { ...common, endpoint: 'https://api.enclave.host/t/metal0', stateRoot: `/var/lib/enclave-host-services/${LABEL}`, dataRoot: `/var/lib/enclave-host-services-data/${LABEL}`,
    packagesDir: `/opt/enclave-host-services/${LABEL}/packages`, dns: { zone: 'app.enclave.host', ipZone: 'ip.enclave.host', nsName: 'ns-metal0.enclave.host',
      nsNames: [...NS, 'ns-metal0.enclave.host'], appStatic }, provenance: { ...provenance, endpoint: 'warden: registry hostId 0x4dde6d1b..., operator 0xC9D0835C...' } };
  const winSpec = { ...common, platform: 'win32', endpoint: 'https://api.enclave.host/t/nucbox-k11-4', stateRoot: `C:\\ProgramData\\Enclave\\host-services\\${LABEL}\\state`,
    dataRoot: `C:\\ProgramData\\Enclave\\host-services\\${LABEL}\\data`, packagesDir: `C:\\Program Files\\Enclave\\host-services\\${LABEL}\\packages`,
    dns: { zone: 'app.enclave.host', ipZone: 'ip.enclave.host', nsName: 'ns-nucbox-k11-4.enclave.host', nsNames: [...NS, 'ns-nucbox-k11-4.enclave.host'], appStatic },
    provenance: { ...provenance, endpoint: 'minipc: keccak256 of this endpoint is 0x2fcef48d..., the runner id of its live leases; public registry row operator 0x1A01194c..., active (outputs/windows-canary-owner-preflight.json); re-confirmed by capture-public-inputs.ps1 before install',
      ports: 'proposed; install.ps1 runs gen-config against this host\'s own listener capture and refuses a port in use' } };
  // 3. bundles (shared by both archives: platform-neutral Node 22)
  const runner = await bundle(TREE, esbuild, 'network/host-services/runner.mjs', 'host-services-runner.mjs', { ownEntryCheck: true });
  const tool = await bundle(TREE, esbuild, 'network/host-services/entries/stage-tool.mjs', 'stage-tool.mjs', { ownEntryCheck: false });
  const { genConfig } = await import(pathToFileURL(path.join(TREE, 'network/host-services/stage-tool.mjs')).href);
  const exe = path.join(HERE, 'out/windows/hostsvc-supervisor.exe');
  if (!fs.existsSync(exe)) throw new Error('out/windows/hostsvc-supervisor.exe is missing: run job-go.sh first');
  const template = fs.readFileSync(path.join(TREE, 'network/host-services/windows-supervisor/supervisor.template.json'));
  if (!template.toString().includes(`\\\\${LABEL}\\\\`) || !template.toString().includes(`-${LABEL}-stop`)) throw new Error(`supervisor.template.json is not for ${LABEL}`);
  const inputs = (extra) => ({ label: LABEL, tree: path.relative(W, TREE), packagesCurrent, pins, runnerClosure: runner.inputs, toolClosure: tool.inputs, appStatic: appStaticInput,
    publicFacts: { ...facts, 'work/adapter-retained/manifest.next.json': BOOTSTRAP_MANIFEST.sha256 }, ...extra });
  const sub = (f) => fs.readFileSync(path.join(HERE, f), 'utf8').replaceAll('@LABEL@', LABEL);
  const out = path.join(outRoot, 'out'), stageRoot = path.join(outRoot, 'stage-r2');
  fs.mkdirSync(out, { recursive: true });
  const results = {};
  for (const target of ['linux', 'windows']) {
    const name = target === 'linux' ? `enclave-host-services-${LABEL}` : `enclave-host-services-${LABEL}-windows`, S = path.join(stageRoot, name);
    fs.rmSync(S, { recursive: true, force: true });
    const dirs = ['bin', 'packages', 'config', 'data', target === 'linux' ? 'systemd' : 'windows', ...(target === 'linux' ? ['scripts'] : [])];
    for (const d of dirs) fs.mkdirSync(path.join(S, d), { recursive: true });
    for (const d of ['', ...dirs]) fs.chmodSync(path.join(S, d), 0o755);
    const put = (rel, data, mode = 0o644) => { fs.writeFileSync(path.join(S, rel), data); fs.chmodSync(path.join(S, rel), mode); };
    for (const role of ROLES4) { const m = JSON.parse(fs.readFileSync(path.join(pkgDir, `${role}.package.json`)));
      put(`packages/${role}.package.json`, fs.readFileSync(path.join(pkgDir, `${role}.package.json`))); put(`packages/${m.bundle}`, fs.readFileSync(path.join(pkgDir, m.bundle))); }
    put('bin/host-services-runner.mjs', runner.bytes); put('bin/stage-tool.mjs', tool.bytes);
    put('data/bootstrap-manifest.json', manifest);
    if (target === 'linux') {
      const listeners = JSON.parse(fs.readFileSync(path.join(HERE, 'root-public-host-facts.json'), 'utf8')).listeners.join('\n');
      put('config/spec.json', JSON.stringify(linuxSpec, null, 2) + '\n');
      put('config/host-services.json', JSON.stringify(genConfig(linuxSpec, listeners), null, 2) + '\n');
      put('systemd/enclave-host-services.service', sub('src/systemd/enclave-host-services.service'));
      for (const f of fs.readdirSync(path.join(HERE, 'src/scripts')).sort()) put(`scripts/${f}`, sub(`src/scripts/${f}`), f === 'common.sh' ? 0o644 : 0o755);
      put('ACTIVATION.txt', sub('src/ACTIVATION.txt'));
      put('STAGE-INPUTS.json', JSON.stringify(inputs({ listeners: sha(fs.readFileSync(path.join(HERE, 'root-public-host-facts.json'))) }), null, 1) + '\n');
    } else {
      put('bin/hostsvc-supervisor.exe', fs.readFileSync(exe));
      put('config/spec.windows.json', JSON.stringify(winSpec, null, 2) + '\n');
      put('config/supervisor.template.json', template);
      for (const f of fs.readdirSync(path.join(HERE, 'src/windows')).sort()) put(`windows/${f}`, sub(`src/windows/${f}`));
      put('ACTIVATION-WINDOWS.txt', sub('src/ACTIVATION-WINDOWS.txt'));
      put('STAGE-INPUTS.json', JSON.stringify(inputs({ supervisorExe: sha(fs.readFileSync(exe)), supervisorBuild: 'job-go.sh: CGO_ENABLED=0 GOOS=windows GOARCH=amd64 go build -trimpath -ldflags="-s -w -buildid="; golang.org/x/sys v0.48.0' }), null, 1) + '\n');
    }
    const files = sums(S);
    results[target] = { ...archive(out, stageRoot, name), files };
  }
  return { packagesCurrent, pins, appStatic: Object.keys(appStatic).length, ...results };
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const tree = flag('--tree');
  if (!tree) { console.error('usage: build-stage-r2.mjs --tree <dir> [--app-static <capture.json>] [--allow-stale-packages] [--out <dir>] [--check]'); process.exit(2); }
  const opts = { tree, appStaticFile: flag('--app-static') || null, allowStale: argv.includes('--allow-stale-packages') };
  const outRoot = path.resolve(flag('--out') || HERE);
  if (argv.includes('--check')) {
    const want = Object.fromEntries(['linux', 'windows'].map((t) => [t, fs.readFileSync(path.join(outRoot, 'out', `enclave-host-services-${LABEL}${t === 'windows' ? '-windows' : ''}.tar.sha256`), 'utf8').split(/\s+/)[0]]));
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'stage-r2-check-'));
    try {
      const r = await build({ ...opts, outRoot: tmp });
      for (const t of ['linux', 'windows']) if (r[t].digest !== want[t]) { console.error(`NOT reproducible (${t}): rebuilt ${r[t].digest}, recorded ${want[t]}`); process.exit(1); }
      console.log(`reproducible: linux ${r.linux.digest}, windows ${r.windows.digest}`);
    } finally { fs.rmSync(tmp, { recursive: true, force: true }); }
  } else console.log(JSON.stringify(await build({ ...opts, outRoot }), null, 1));
}
